import math
from scipy.integrate import dblquad, tplquad


def sphere_flux(F, R):
    def g(ph, th):
        n = (R*R*math.sin(ph)**2*math.cos(th),
             R*R*math.sin(ph)**2*math.sin(th),
             R*R*math.sin(ph)*math.cos(ph))
        p = (R*math.sin(ph)*math.cos(th), R*math.sin(ph)*math.sin(th),
             R*math.cos(ph))
        f = F(*p)
        return f[0]*n[0] + f[1]*n[1] + f[2]*n[2]
    return dblquad(g, 0, 2*math.pi, lambda th: 0, lambda th: math.pi)[0]


def ball_divergence(div, R):
    def g(rho, ph, th):
        x = rho*math.sin(ph)*math.cos(th)
        y = rho*math.sin(ph)*math.sin(th)
        z = rho*math.cos(ph)
        return div(x, y, z) * rho*rho*math.sin(ph)
    return tplquad(g, 0, 2*math.pi, lambda th: 0, lambda th: math.pi,
                   lambda th, ph: 0, lambda th, ph: R)[0]
